"""Native API envelopes for completions generated by the owned checkpoint."""

from __future__ import annotations

import json


def native_completion(response, dialect) -> dict:
    from verifiers.v1.clients.train import serialize_completion
    from verifiers.v1.dialects import AnthropicDialect, ChatDialect, ResponsesDialect

    message = response.message
    usage = response.usage
    if isinstance(dialect, ChatDialect):
        raw = serialize_completion(response, response.model)
    elif isinstance(dialect, AnthropicDialect):
        content = []
        if message.reasoning_content:
            content.append({"type": "thinking", "thinking": message.reasoning_content, "signature": ""})
        if message.content is not None:
            content.append({"type": "text", "text": message.content})
        for call in message.tool_calls or ():
            arguments = json.loads(call.arguments)
            if call.type != "function" or not isinstance(arguments, dict):
                raise ValueError("native message tools require JSON object arguments")
            content.append({"type": "tool_use", "id": call.id, "name": call.name, "input": arguments})
        raw = {"id": response.id, "type": "message", "role": "assistant", "model": response.model,
               "content": content or [{"type": "text", "text": ""}],
               "stop_reason": {"length": "max_tokens", "tool_calls": "tool_use"}.get(response.finish_reason, "end_turn"),
               "stop_sequence": None,
               "usage": {"input_tokens": usage.input_tokens, "output_tokens": usage.completion_tokens}}
    elif isinstance(dialect, ResponsesDialect):
        output = []
        if message.reasoning_content:
            output.append({"id": response.id + "_reasoning", "type": "reasoning",
                           "summary": [{"type": "summary_text", "text": message.reasoning_content}]})
        if message.content is not None:
            output.append({"id": response.id + "_message", "type": "message", "role": "assistant",
                           "status": "completed", "content": [{"type": "output_text", "text": message.content,
                                                                 "annotations": []}]})
        for call in message.tool_calls or ():
            if call.type != "function":
                raise ValueError("native response tools require function calls")
            output.append({"id": response.id + "_" + call.id, "type": "function_call", "call_id": call.id,
                           "name": call.name, "arguments": call.arguments, "status": "completed"})
        raw = {"id": response.id, "object": "response", "created_at": response.created,
               "model": response.model, "status": "incomplete" if response.finish_reason == "length" else "completed",
               "error": None, "incomplete_details": {"reason": "max_output_tokens"} if response.finish_reason == "length" else None,
               "output": output, "parallel_tool_calls": False, "tools": [], "tool_choice": "auto",
               "usage": {"input_tokens": usage.input_tokens, "output_tokens": usage.completion_tokens,
                         "total_tokens": usage.total_tokens}}
    else:
        raise ValueError("unsupported local model dialect")
    dialect.validate_response(raw)
    return raw


def completion_events(raw: dict, dialect):
    """Complete native SSE events, including tools; no provider request is made."""
    from verifiers.v1.dialects import AnthropicDialect, ChatDialect, ResponsesDialect

    def event(kind, body, *, named=False):
        prefix = f"event: {kind}\n" if named else ""
        return (prefix + "data: " + json.dumps(body, allow_nan=False) + "\n\n").encode()

    if isinstance(dialect, ChatDialect):
        choice = raw["choices"][0]
        delta = dict(choice["message"])
        if delta.get("tool_calls"):
            delta["tool_calls"] = [{"index": index, **call} for index, call in enumerate(delta["tool_calls"])]
        common = {key: raw[key] for key in ("id", "created", "model")}
        yield event(None, {**common, "object": "chat.completion.chunk", "choices": [
            {"index": 0, "delta": delta, "finish_reason": None}]})
        yield event(None, {**common, "object": "chat.completion.chunk", "usage": raw["usage"], "choices": [
            {"index": 0, "delta": {}, "finish_reason": choice["finish_reason"]}]})
        yield b"data: [DONE]\n\n"
    elif isinstance(dialect, AnthropicDialect):
        yield event("message_start", {"type": "message_start", "message": {
            **raw, "content": [], "stop_reason": None, "usage": {**raw["usage"], "output_tokens": 0}}}, named=True)
        for index, block in enumerate(raw["content"]):
            kind = block["type"]
            field = {"text": "text", "thinking": "thinking", "tool_use": "input"}[kind]
            yield event("content_block_start", {"type": "content_block_start", "index": index,
                "content_block": {**block, field: {} if kind == "tool_use" else ""}}, named=True)
            delta = ({"type": "input_json_delta", "partial_json": json.dumps(block["input"], allow_nan=False)}
                     if kind == "tool_use" else {"type": field + "_delta", field: block[field]})
            yield event("content_block_delta", {"type": "content_block_delta", "index": index, "delta": delta}, named=True)
            yield event("content_block_stop", {"type": "content_block_stop", "index": index}, named=True)
        yield event("message_delta", {"type": "message_delta", "delta": {
            "stop_reason": raw["stop_reason"], "stop_sequence": None}, "usage": raw["usage"]}, named=True)
        yield event("message_stop", {"type": "message_stop"}, named=True)
    elif isinstance(dialect, ResponsesDialect):
        sequence = 0

        def response_event(kind, body):
            nonlocal sequence
            result = event(kind, {"type": kind, "sequence_number": sequence, **body})
            sequence += 1
            return result

        head = {**raw, "status": "in_progress", "output": [], "usage": None}
        yield response_event("response.created", {"response": head})
        yield response_event("response.in_progress", {"response": head})
        for index, item in enumerate(raw["output"]):
            common = {"output_index": index, "item_id": item["id"]}
            kind = item["type"]
            initial = ({**item, "arguments": "", "status": "in_progress"} if kind == "function_call"
                       else {**item, "summary": []} if kind == "reasoning"
                       else {**item, "content": [], "status": "in_progress"})
            yield response_event("response.output_item.added", {"output_index": index, "item": initial})
            if kind == "function_call":
                yield response_event("response.function_call_arguments.delta", {**common, "delta": item["arguments"]})
                yield response_event("response.function_call_arguments.done", {**common, "arguments": item["arguments"]})
            else:
                reasoning = kind == "reasoning"
                for part_index, part in enumerate(item["summary" if reasoning else "content"]):
                    position = {**common, "summary_index" if reasoning else "content_index": part_index}
                    prefix = "response.reasoning_summary" if reasoning else "response.content"
                    yield response_event(prefix + "_part.added", {**position, "part": {**part, "text": ""}})
                    text_prefix = "response.reasoning_summary_text" if reasoning else "response.output_text"
                    yield response_event(text_prefix + ".delta", {**position, "delta": part["text"]})
                    yield response_event(text_prefix + ".done", {**position, "text": part["text"]})
                    yield response_event(prefix + "_part.done", {**position, "part": part})
            yield response_event("response.output_item.done", {"output_index": index, "item": item})
        terminal = "response.incomplete" if raw["status"] == "incomplete" else "response.completed"
        yield response_event(terminal, {"response": raw})
        yield b"data: [DONE]\n\n"
    else:
        raise ValueError("unsupported local model dialect")
